  --bg-dialog:      #1e2130;
  --border:         #2e3249;
  --accent-red:     #e0414b;
  --accent-red-hover: #f25560;
  --accent-ghost:   #2e3249;
  --accent-ghost-hover: #3a3f5c;
  --text-primary:   #e8eaf6;
  --text-secondary: #8b90b0;
  --text-muted:     #555b7a;
  --radius-sm:      6px;
  --radius-md:      12px;
  --radius-lg:      18px;
  --shadow-dialog:  0 24px 80px rgba(0,0,0,0.6), 0 4px 16px rgba(0,0,0,0.4);
  --transition:     180ms cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px 20px;
}

/* ─── Page Layout ──────────────────────────────────────────────────────────── */
.page-header {
  width: 100%;
  max-width: 860px;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 36px;
}

.page-header h1 {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.01em;
}

.page-header .breadcrumb {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.page-header .breadcrumb span { color: var(--text-secondary); }

/* ─── Image Preview Card ───────────────────────────────────────────────────── */
.preview-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 860px;
  overflow: hidden;
}

.preview-card__image-wrap {
  position: relative;
  background: #11131e;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  border-bottom: 1px solid var(--border);
  min-height: 380px;
}

/* Placeholder image using SVG / CSS art */
.preview-card__image-wrap .img-placeholder {
  width: 340px;
  max-width: 100%;
  aspect-ratio: 4/3;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, #1c2a4a 0%, #2a1c3f 50%, #1a2a1c 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.preview-card__image-wrap .img-placeholder::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 30%, rgba(100,140,255,0.18) 0%, transparent 60%),
    radial-gradient(circle at 70% 70%, rgba(180,100,255,0.14) 0%, transparent 55%);
}

.img-placeholder__icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: var(--text-muted);
  font-size: 0.78rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  position: relative;
}

.img-placeholder__icon svg {
  width: 48px;
  height: 48px;
  opacity: 0.5;
}

.preview-card__meta {
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.meta-info { display: flex; flex-direction: column; gap: 4px; }

.meta-info__title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.meta-info__details {
  font-size: 0.8rem;
  color: var(--text-secondary);
  display: flex;
  gap: 14px;
}

.meta-info__details span::before {
  content: "·";
  margin-right: 14px;
}

.meta-info__details span:first-child::before { content: none; }

.card-actions { display: flex; gap: 10px; align-items: center; }

/* ─── Buttons ──────────────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  padding: 8px 16px;
  transition: background var(--transition), color var(--transition), box-shadow var(--transition);
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
}

.btn svg { flex-shrink: 0; }

.btn--ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--accent-ghost);
}

.btn--ghost:hover {
  background: var(--accent-ghost-hover);
  color: var(--text-primary);
}

.btn--danger {
  background: var(--accent-red);
  color: #fff;
}

.btn--danger:hover {
  background: var(--accent-red-hover);
  box-shadow: 0 0 0 3px rgba(224,65,75,0.25);
}

.btn--danger-outline {
  background: transparent;
  color: var(--accent-red);
  border: 1px solid var(--accent-red);
}

.btn--danger-outline:hover {
  background: rgba(224,65,75,0.1);
  box-shadow: 0 0 0 3px rgba(224,65,75,0.15);
}

.btn:focus-visible {
  outline: 2px solid #6c8fff;
  outline-offset: 2px;
}

/* ─── Modal Overlay ────────────────────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg-overlay);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 1000;

  /* Hidden by default */
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
}

.modal-overlay[aria-hidden="false"] {
  opacity: 1;
  pointer-events: auto;
}

/* ─── Modal Dialog ─────────────────────────────────────────────────────────── */
.modal-dialog {
  background: var(--bg-dialog);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  width: 100%;
  max-width: 440px;
  overflow: hidden;

  transform: translateY(12px) scale(0.97);
  transition: transform var(--transition);
}

.modal-overlay[aria-hidden="false"] .modal-dialog {
  transform: translateY(0) scale(1);
}

/* Warning stripe at top */
.modal-dialog__stripe {
  height: 4px;
  background: linear-gradient(90deg, var(--accent-red), #ff8a65);
}

.modal-dialog__body {
  padding: 28px 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.modal-dialog__icon-row {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}

.modal-icon-badge {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(224,65,75,0.12);
  border: 1px solid rgba(224,65,75,0.28);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-red);
}

.modal-icon-badge svg { width: 22px; height: 22px; }

.modal-dialog__text { display: flex; flex-direction: column; gap: 6px; }

.modal-dialog__title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.modal-dialog__desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.55;
}

.modal-dialog__desc strong {
  color: var(--text-primary);
  font-weight: 600;
}

/* Preview thumbnail inside dialog */
.modal-dialog__preview {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(255,255,255,0.04);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
}

.modal-dialog__preview .thumb {
  width: 44px;
