.modal-dialog__preview .thumb-size { font-size: 0.75rem; color: var(--text-muted); }

.modal-dialog__footer {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  padding: 0 28px 24px;
}

/* ─── Close button ─────────────────────────────────────────────────────────── */
.modal-close {
  position: absolute;
  top: 14px;
  right: 14px;
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  border-radius: var(--radius-sm);
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color var(--transition), background var(--transition);
}

.modal-close:hover { color: var(--text-primary); background: var(--accent-ghost); }
.modal-close:focus-visible { outline: 2px solid #6c8fff; outline-offset: 2px; }

.modal-dialog { position: relative; }
