+  border: 1px solid rgba(224,65,75,0.28);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--accent-red);
+}
+
+.modal-icon-badge svg { width: 22px; height: 22px; }
+
+.modal-dialog__text { display: flex; flex-direction: column; gap: 6px; }
+
+.modal-dialog__title {
+  font-size: 1.05rem;
+  font-weight: 700;
+  color: var(--text-primary);
+  line-height: 1.2;
+}
+
+.modal-dialog__desc {
+  font-size: 0.875rem;
+  color: var(--text-secondary);
+  line-height: 1.55;
+}
+
+.modal-dialog__desc strong {
+  color: var(--text-primary);
+  font-weight: 600;
